class Account:
    def __init__(self, accountNumber, balance, pin):
        self.accountNumber = accountNumber
        self.__balance = balance
        self.__pin = pin

    def get_public_accountNumber(self):
        return self.accountNumber

    def get_protected_balance(self, p):
        if p == self.__pin:
            return self.__balance
        return -1

    def get_private_pin(self, account_type):
        return self.__pin

class SavingsAccount(Account):
    def __init__(self, accountNumber, balance, pin):
        super().__init__(accountNumber, balance, pin)

    def display(self):
        print(f"Savings Account: {self.accountNumber} {self.get_protected_balance(self.__pin)}")

    def __pin(self):
        return super().get_private_pin("Savings")

class SecureAccount(Account):
    def __init__(self, accountNumber, balance, pin):
        super().__init__(accountNumber, balance, pin)

    def display(self):
        print("Secure Account: Access Restricted")

def main():
    import sys
    data = sys.stdin.read().strip().split()
    if len(data) < 3:
        return

    accountNumber = int(data[0])
    balance = int(data[1])
    pin = int(data[2])

    sa = SavingsAccount(accountNumber, balance, pin)
    sa.display()

    sec = SecureAccount(accountNumber, balance, pin)
    sec.display()

    sa.display()
    sec.display()

if __name__ == "__main__":
    main()
